package EmployeeManagementSystem.service;
import EmployeeManagementSystem.entity.TaxDeclaration; import EmployeeManagementSystem.repository.TaxDeclarationRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.*;
@Service public class TaxDeclarationServiceImpl implements TaxDeclarationService{
 private final TaxDeclarationRepository repo; public TaxDeclarationServiceImpl(TaxDeclarationRepository r){repo=r;}
 public List<TaxDeclaration> my(String u){return repo.findByUserIdOrderByFinancialYearDescCreatedAtDesc(u);} public List<TaxDeclaration> all(){return repo.findAllByOrderByCreatedAtDesc();}
 @Transactional public TaxDeclaration create(TaxDeclaration x,String u,String n){if(x==null||x.getFinancialYear()==null||x.getFinancialYear().isBlank())throw new IllegalArgumentException("Financial year is required.");if(repo.findByUserIdAndFinancialYear(u,x.getFinancialYear()).isPresent())throw new IllegalArgumentException("A tax declaration already exists for this financial year."); x.setId(null);x.setUserId(u);x.setEmployeeName(n);x.setDeclarationNumber("TAX-"+System.currentTimeMillis());x.setStatus("DRAFT");x.setReviewerUserId(null);x.setReviewerComment(null);x.setReviewedAt(null);x.calculate();return repo.save(x);}
 @Transactional public TaxDeclaration submit(Long id,String u){TaxDeclaration x=repo.findById(id).orElseThrow(()->new NoSuchElementException("Declaration not found."));if(!u.equals(x.getUserId()))throw new IllegalArgumentException("You can submit only your own declaration.");if(!Set.of("DRAFT","REJECTED").contains(x.getStatus()))throw new IllegalArgumentException("Only draft or rejected declarations can be submitted.");x.setStatus("SUBMITTED");x.setSubmittedAt(LocalDateTime.now());x.setReviewerComment(null);return repo.save(x);}
 @Transactional public TaxDeclaration review(Long id,String status,String comment,String reviewer){TaxDeclaration x=repo.findById(id).orElseThrow(()->new NoSuchElementException("Declaration not found."));if(!Set.of("UNDER_REVIEW","APPROVED","REJECTED").contains(status))throw new IllegalArgumentException("Invalid review status.");if("APPROVED".equals(status)&&x.getProofReference()==null)throw new IllegalArgumentException("Proof reference is required before approval.");x.setStatus(status);x.setReviewerUserId(reviewer);x.setReviewerComment(comment);x.setReviewedAt(LocalDateTime.now());return repo.save(x);}
}
